/**
 * Discovery Engine
 *
 * Core discovery orchestration that coordinates finding and registering
 * tools, agents, resources, prompts, and workflows.
 */
import { detectPlatform } from "../platform/core-platform.js";
import { agentLogger } from "../utils/index.js";
import { ensureError } from "../errors/index.js";
import { isExplicitHostProjectCodeExecutionAllowed } from "../security/project-locality.js";
import { registerSkill, skillRegistry } from "../skill/registry.js";
import { importModule } from "./transpiler.js";
import { findTypeScriptFiles } from "./file-discovery.js";
import { agentHandler, discoverSkills, evalHandler, promptHandler, resourceHandler, scheduleHandler, taskHandler, toolHandler, webhookHandler, workflowHandler, } from "./handlers/index.js";
import { discoverRuntimeAgentMarkdownDefinitions } from "./handlers/runtime-agent-markdown-handler.js";
import { filenameToId } from "./discovery-utils.js";
const logger = agentLogger.component("discovery");
function isIndexModule(file) {
    const normalized = file.replace("file://", "");
    return /(?:^|\/)index\.(?:ts|tsx|js|jsx)$/.test(normalized);
}
function compareDiscoveryFiles(a, b) {
    const aIsIndex = isIndexModule(a);
    const bIsIndex = isIndexModule(b);
    if (aIsIndex !== bIsIndex)
        return aIsIndex ? 1 : -1;
    return a.localeCompare(b);
}
function resolveDiscoveryDir(baseDir, dir) {
    if (baseDir === "")
        return dir;
    return `${baseDir}/${dir}`;
}
function collectNamedDiscoveryCandidates(module, handler, onError) {
    const candidates = [];
    for (const [exportName, value] of Object.entries(module)) {
        if (exportName === "default")
            continue;
        try {
            if (!handler.validate(value))
                continue;
            candidates.push({
                exportName,
                item: value,
                prepared: handler.prepare?.(value),
            });
        }
        catch (error) {
            onError(error);
        }
    }
    return candidates;
}
function getCandidateId(candidate, file, dir, handler, useExportNameFallback) {
    const derivedId = handler.getId(candidate.item, file, dir);
    if (!useExportNameFallback)
        return derivedId;
    const fileId = filenameToId(file);
    if (derivedId !== fileId)
        return derivedId;
    return candidate.exportName;
}
/**
 * Discover items of a specific type in a directory
 */
async function discoverItems(dir, result, context, handler, verbose) {
    const files = (await findTypeScriptFiles(dir, context)).sort(compareDiscoveryFiles);
    const resultMap = handler.getResultMap(result);
    if (verbose) {
        logger.info(`Found ${files.length} ${handler.typeName} files in ${dir}`);
    }
    for (const file of files) {
        let module;
        try {
            module = await importModule(file, context);
        }
        catch (error) {
            result.errors.push({ file, error: ensureError(error) });
            if (verbose) {
                logger.error(`Error loading ${file}:`, error);
            }
            continue;
        }
        const recordCandidateError = (error) => {
            result.errors.push({ file, error: ensureError(error) });
            if (verbose) {
                logger.error(`Error registering ${handler.typeName} from ${file}:`, error);
            }
        };
        let defaultCandidate;
        try {
            const defaultItem = module.default;
            if (handler.validate(defaultItem)) {
                defaultCandidate = {
                    exportName: "default",
                    item: defaultItem,
                    prepared: handler.prepare?.(defaultItem),
                };
            }
        }
        catch (error) {
            recordCandidateError(error);
        }
        if (defaultCandidate !== undefined) {
            try {
                const id = getCandidateId(defaultCandidate, file, dir, handler, isIndexModule(file));
                if (resultMap.has(id)) {
                    if (verbose) {
                        logger.warn(`Duplicate ${handler.typeName} "${id}" in ${file}; keeping first`);
                    }
                    continue;
                }
                const registered = handler.register(id, defaultCandidate.item, file, dir, "default", defaultCandidate.prepared);
                resultMap.set(id, registered);
                if (verbose)
                    logger.info(`Registered ${handler.typeName}: ${id}`);
                continue;
            }
            catch (error) {
                recordCandidateError(error);
            }
        }
        let candidates;
        try {
            candidates = collectNamedDiscoveryCandidates(module, handler, recordCandidateError);
        }
        catch (error) {
            recordCandidateError(error);
            continue;
        }
        if (candidates.length === 0) {
            if (verbose) {
                logger.warn(`${file} does not export a valid ${handler.typeName}`);
            }
            continue;
        }
        const useExportNameFallback = candidates.length > 1 || isIndexModule(file);
        for (const candidate of candidates) {
            try {
                const id = getCandidateId(candidate, file, dir, handler, useExportNameFallback);
                if (resultMap.has(id)) {
                    if (verbose) {
                        logger.warn(`Duplicate ${handler.typeName} "${id}" in ${file}; keeping first`);
                    }
                    continue;
                }
                const registered = handler.register(id, candidate.item, file, dir, candidate.exportName, candidate.prepared);
                resultMap.set(id, registered);
                if (verbose) {
                    logger.info(`Registered ${handler.typeName}: ${id} (export: ${candidate.exportName})`);
                }
            }
            catch (error) {
                recordCandidateError(error);
            }
        }
    }
}
async function discoverConfiguredItems(dirs, defaultDirs, baseDir, result, context, handler, verbose) {
    for (const dir of dirs ?? defaultDirs) {
        await discoverItems(resolveDiscoveryDir(baseDir, dir), result, context, handler, verbose);
    }
}
/**
 * Discover all items in configured directories
 */
export async function discoverAll(config) {
    if (!isExplicitHostProjectCodeExecutionAllowed(config)) {
        throw new TypeError("Executable project discovery requires explicit trusted-local execution");
    }
    const baseDir = config.baseDir;
    const context = {
        platform: detectPlatform(),
        fsAdapter: config.fsAdapter,
        cacheNamespace: config.cacheNamespace,
        baseDir,
        allowHostProjectCodeExecution: true,
        assertCurrent: config.assertCurrent,
    };
    const result = {
        tools: new Map(),
        agents: new Map(),
        skills: new Map(),
        resources: new Map(),
        prompts: new Map(),
        workflows: new Map(),
        tasks: new Map(),
        schedules: new Map(),
        webhooks: new Map(),
        evals: new Map(),
        errors: [],
    };
    // Discover tools
    await discoverConfiguredItems(config.toolDirs, ["tools"], baseDir, result, context, toolHandler, config.verbose);
    // Clear stale skills before any skill registration so deleted/renamed
    // skills are removed. Global skills are discovered BEFORE agents so that
    // directory-agent colocated skills (registered during agent discovery)
    // survive the clear and owned-short-name shadow diagnostics can see the
    // global ids they shadow.
    skillRegistry.clear();
    // Discover skills (parallel path — markdown-based, not TypeScript import)
    for (const dir of config.skillDirs ?? ["skills"]) {
        const skillResult = await discoverSkills(resolveDiscoveryDir(baseDir, dir), context, config.verbose);
        for (const [id, skill] of skillResult.skills) {
            if (result.skills.has(id)) {
                logger.warn(`Duplicate skill "${id}" across discovery roots; keeping first registration`);
                continue;
            }
            registerSkill(id, skill);
            result.skills.set(id, skill);
        }
        result.errors.push(...skillResult.errors.map((e) => ({ file: e.file, error: e.error })));
    }
    // Discover agents
    for (const dir of config.agentDirs ?? ["agents"]) {
        const agentDir = resolveDiscoveryDir(baseDir, dir);
        await discoverItems(agentDir, result, context, agentHandler, config.verbose);
        await discoverRuntimeAgentMarkdownDefinitions(agentDir, result, context);
    }
    // Discover resources
    await discoverConfiguredItems(config.resourceDirs, ["resources"], baseDir, result, context, resourceHandler, config.verbose);
    // Discover prompts
    await discoverConfiguredItems(config.promptDirs, ["prompts"], baseDir, result, context, promptHandler, config.verbose);
    // Discover workflows
    await discoverConfiguredItems(config.workflowDirs, ["workflows"], baseDir, result, context, workflowHandler, config.verbose);
    // Discover tasks
    await discoverConfiguredItems(config.taskDirs, ["tasks"], baseDir, result, context, taskHandler, config.verbose);
    // Discover schedules
    await discoverConfiguredItems(config.scheduleDirs, ["schedules"], baseDir, result, context, scheduleHandler, config.verbose);
    // Discover webhooks
    await discoverConfiguredItems(config.webhookDirs, ["webhooks"], baseDir, result, context, webhookHandler, config.verbose);
    // Discover eval definitions
    await discoverConfiguredItems(config.evalDirs, ["evals"], baseDir, result, context, evalHandler, config.verbose);
    return result;
}
